mapper.select:
SELECT
id, title, description, status, due_date, created_at, updated_at
FROM todos


    AND title LIKE CONCAT('%', #{title}, '%')


    AND status = #{status}


    AND description LIKE CONCAT('%', #{description}, '%')


    AND due_date >= #{dueDate}



  ORDER BY ${orderByClause}


  ORDER BY id ASC

LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM todos


    AND title LIKE CONCAT('%', #{title}, '%')


    AND status = #{status}


    AND description LIKE CONCAT('%', #{description}, '%')


    AND due_date >= #{dueDate}

